ee:message.ee:set-payload:
%dw 2.0
output application/xml

fun dynAttrNs(xsi: Namespace, value: Any) = { subscribers @(xsi#noNamespaceSchemaLocation: "xsd/ModificarDatosCuentaInput.xsd"): value }
var namespace1 = {uri: "http://www.w3.org/2001/XMLSchema-instance", prefix: "xsi"} as Namespace

var data = payload.subscribers.subscriber_particulars
---

dynAttrNs(namespace1,{
        subscriber_particulars: {
            subscriber_data @(action: data.subscriber_data.action): {
                user: data.subscriber_data.user,
                subscriber_id: data.subscriber_data.subscriber_id,
                first_name: data.subscriber_data.first_name,
                last_name: data.subscriber_data.last_name,
                subscriber_name: data.subscriber_data.subscriber_name
            },
            billing_address_data @(action: data.billing_address_data.action):{
                bill_address1: data.billing_address_data.bill_address1,
                bill_city: data.billing_address_data.bill_city,
                bill_country_code: data.billing_address_data.bill_country_code,
                bill_state_code: data.billing_address_data.bill_state_code
            },
            address_data @(action: data.address_data.action):{
                address1: data.address_data.address1,
                address_geo_code: data.address_data.address_geo_code,
                city: data.address_data.city,
                country_code: data.address_data.country_code,
                state_code: data.address_data.state_code
            },
            email_data @(action: data.email_data.action):{
                email_address: data.email_data.email_address,
                email_is_primary_flag: data.email_data.email_is_primary_flag
            },
            invoice_method_data @(action: data.invoice_method_data.action):{
                invoice_method_name: data.invoice_method_data.invoice_method_name,
                invoice_delivery_name: data.invoice_method_data.invoice_delivery_name
            }
        }
    })

%dw 2.0
output application/json
---
{
	operation: payload.response.@operation,
	result: payload.response.@result,
	system: payload.response.@system,
	faults:
	{
		subscriber_id: payload.response.faults.subscriber_id,
		fault_detail: payload.response.faults.fault_detail.@
	}
}
